#!/usr/bin/env node
/**
 * Build the engine specifications (Oct 19, 2026) into docs/engines/:
 *   docs/engines/<slug>.md   one page per engine
 *   docs/engines/README.md   index table
 *   docs/engines/specs.json  every spec, for the skills site and the MCP server
 *
 *   node platform/scripts/generate-engine-specs.mjs           # write
 *   node platform/scripts/generate-engine-specs.mjs --check   # exit 1 if a spec is
 *     incomplete, an engine gained a network, file-write or process call, or the
 *     generated files are stale
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { join, dirname, resolve, basename } from "node:path";
import { fileURLToPath } from "node:url";
import { listSkills } from "../lib/catalog.mjs";
import { buildSpec, validateSpecSource, loadSpecSource, loadEnvironments, renderSpecMarkdown } from "../lib/specs.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const OUT = join(ROOT, "docs", "engines");
const check = process.argv.includes("--check");

const env = loadEnvironments(ROOT);
const specs = [];
const errors = [];

for (const s of listSkills(ROOT)) {
  if (!s.hasEngine) continue;
  errors.push(...validateSpecSource(s.slug, loadSpecSource(s)));
  for (const f of s.jsFiles) {
    const id = s.jsFiles.length === 1 ? s.slug : `${s.slug}:${basename(f, ".js")}`;
    const spec = buildSpec(s, join(s.resourcesDir, f), id, env);
    if (!spec.acts.analyzes_only) {
      errors.push(`${id}: the engine now makes network calls, writes files or starts processes. Engines must only compute; if this is intended, the specs' "analyzes only" line and the README's data section must change first.`);
    }
    if (!spec.inputs) errors.push(`${id}: SKILL.md has no metadata.inputs`);
    if (!spec.outputs) errors.push(`${id}: SKILL.md has no metadata.outputs`);
    specs.push(spec);
  }
}

const files = new Map();
for (const spec of specs) files.set(`${spec.slug}.md`, renderSpecMarkdown(spec));
files.set("specs.json", JSON.stringify({
  $comment: "Generated by platform/scripts/generate-engine-specs.mjs. Do not edit; change skills/<slug>/spec.json or SKILL.md.",
  engines: specs,
}, null, 2) + "\n");
files.set("README.md", `# Engine specifications

<!-- Generated by platform/scripts/generate-engine-specs.mjs. Do not edit. -->

One page per engine: the decision it supports, its inputs and output, setup, whether it acts or only analyzes, where your information goes, and its limitations and review requirement. Every engine only analyzes: none makes network calls, writes files or changes anything in your tools (checked in CI). Where your inputs travel depends on how you run it; see [what happens to your data](../../README.md#what-happens-to-your-data).

| Engine | Phase | Decision it supports |
|---|---|---|
${specs.map((s) => `| [${s.title}](${s.slug}.md) | ${s.phase} | ${s.decision.replace(/\|/g, "\\|")} |`).join("\n")}
`);

if (errors.length) {
  console.error(`Engine specs: ${errors.length} problem(s)\n` + errors.map((e) => `  - ${e}`).join("\n"));
  process.exit(1);
}

if (check) {
  const stale = [];
  for (const [name, body] of files) {
    const p = join(OUT, name);
    if (!existsSync(p) || readFileSync(p, "utf8") !== body) stale.push(name);
  }
  if (existsSync(OUT)) for (const f of readdirSync(OUT)) if (!files.has(f)) stale.push(`${f} (no longer generated)`);
  if (stale.length) {
    console.error(`Engine specs are stale: ${stale.slice(0, 8).join(", ")}${stale.length > 8 ? "…" : ""}\nRun: node platform/scripts/generate-engine-specs.mjs`);
    process.exit(1);
  }
  console.log(`Engine specs up to date — ${specs.length} engines, all analyze only.`);
} else {
  mkdirSync(OUT, { recursive: true });
  for (const f of readdirSync(OUT)) if (!files.has(f)) rmSync(join(OUT, f));
  for (const [name, body] of files) writeFileSync(join(OUT, name), body);
  console.log(`Wrote docs/engines/ — ${specs.length} engine specs.`);
}
